//! Generated protobuf + gRPC bindings for Paigasus (prost + tonic).
//!
//! Source of truth: `contracts/proto`; generated by `buf generate` into
//! `src/generated/` and committed (ADR-0004). Regenerate via
//! `moon run contracts:generate`.

// Lets the ABSOLUTE path `::paigasus_proto::…` resolve INSIDE this crate. The Auditable derive
// is injected onto generated messages here (contracts/buf.gen.yaml), and a derive crate cannot
// depend on paigasus-proto — that is the cycle — so its output must name the trait absolutely.
// Same trick serde uses. THIS LINE LOOKS REMOVABLE AND IS NOT: deleting it breaks every
// generated `#[derive(::paigasus_proto::audit::Auditable)]` (SMA-438 F2).
extern crate self as paigasus_proto;

pub mod paigasus {
    pub mod gateway {
        pub mod v1 {
            // Generated code is excluded from the strict lint gate.
            #![allow(clippy::all, warnings)]
            include!("generated/paigasus/gateway/v1/paigasus.gateway.v1.rs");
            include!("generated/paigasus/gateway/v1/paigasus.gateway.v1.tonic.rs");
        }
    }
    pub mod common {
        pub mod v1 {
            // Generated code is excluded from the strict lint gate.
            #![allow(clippy::all, warnings)]
            // service_info.proto declares ServiceInfoService, so neoeinstein-tonic
            // now emits a `.tonic.rs` for this package alongside the prost file
            // (SMA-499). Before that, audit.proto declared no service and this
            // package was prost-only.
            include!("generated/paigasus/common/v1/paigasus.common.v1.rs");
            include!("generated/paigasus/common/v1/paigasus.common.v1.tonic.rs");
        }
    }
    pub mod iam {
        pub mod v1 {
            // Generated code is excluded from the strict lint gate.
            #![allow(clippy::all, warnings)]
            include!("generated/paigasus/iam/v1/paigasus.iam.v1.rs");
            include!("generated/paigasus/iam/v1/paigasus.iam.v1.tonic.rs");
        }
    }
}

/// Thin `Auditable` contract layered on the generated `common::v1::AuditMetadata`.
pub mod audit;

/// Wire-key transform for the `Capability` registry in `common::v1`.
pub mod capability;

/// Wire-string helpers for the canonical error registry (`common::v1::ErrorReason`/`ErrorDomain`).
pub mod error;
